SELECT "t2"."line_id", "t2"."qty_ok", "t2"."qty_bad", "t2"."last_received", 'complete' AS "route", 'receipts' AS "context"
FROM (SELECT "t"."line_id", COALESCE(SUM(CASE WHEN "p_3fc03684"."condition" = 'ok' THEN "p_3fc03684"."quantity" ELSE 0 END), 0) AS "qty_ok", COALESCE(SUM(CASE WHEN "p_3fc03684"."condition" <> 'ok' THEN "p_3fc03684"."quantity" ELSE 0 END), 0) AS "qty_bad", MAX("p_3fc03684"."received_date") AS "last_received"
        FROM (SELECT "p_da15c438"."line_id", "p_da15c438"."request_number", "p_da15c438"."item", "p_da15c438"."quantity", "p_da15c438"."way", "p_da15c438"."customer0" AS "customer", "p_da15c438"."email" AS "customer_email", "p_7d39f2a5"."id" AS "obligation_id", "p_7d39f2a5"."due", "p_7d39f2a5"."state" AS "obligation_state"
                FROM "p_da15c438"
                    INNER JOIN "p_7d39f2a5" ON "p_7d39f2a5"."entity" = 'return_request_line' AND "p_7d39f2a5"."key" = CAST("p_da15c438"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a5"."kind" = 'inbound' AND "p_7d39f2a5"."state" IN ('open', 'overdue', 'reopened')) AS "t"
            LEFT JOIN "p_3fc03684" ON "t"."line_id" = "p_3fc03684"."line_id"
        GROUP BY "t"."line_id") AS "t2"
    INNER JOIN (SELECT "line_id"
        FROM (SELECT "t17"."line_id", "t17"."request_number", "t17"."item", "t17"."quantity", "t17"."way", "t17"."customer", "t17"."customer_email", "t17"."obligation_id", "t17"."due", "t17"."obligation_state", "t17"."qty_ok", "t17"."qty_bad", "t17"."last_received", "t17"."days_open", "t19"."reminders", CASE WHEN "t17"."qty_ok" >= "t17"."quantity" THEN 'complete' WHEN "t17"."qty_bad" > 0 OR "t17"."qty_ok" > 0 AND "t17"."qty_ok" < "t17"."quantity" THEN 'damaged' WHEN "t17"."days_open" > :inbound_close THEN 'expired' WHEN "t17"."days_open" > :inbound_reminder AND "t19"."reminders" = 0 THEN 'remind' ELSE NULL END AS "route"
                FROM (SELECT "t8"."line_id", "t8"."request_number", "t8"."item", "t8"."quantity", "t8"."way", "t8"."customer", "t8"."customer_email", "t8"."obligation_id", "t8"."due", "t8"."obligation_state", "t8"."qty_ok", "t8"."qty_bad", "t8"."last_received", "t16"."days_open"
                        FROM (SELECT "t3"."line_id", "t3"."request_number", "t3"."item", "t3"."quantity", "t3"."way", "t3"."customer", "t3"."customer_email", "t3"."obligation_id", "t3"."due", "t3"."obligation_state", "t7"."qty_ok", "t7"."qty_bad", "t7"."last_received"
                                FROM (SELECT "p_da15c4380"."line_id", "p_da15c4380"."request_number", "p_da15c4380"."item", "p_da15c4380"."quantity", "p_da15c4380"."way", "p_da15c4380"."customer0" AS "customer", "p_da15c4380"."email" AS "customer_email", "p_7d39f2a50"."id" AS "obligation_id", "p_7d39f2a50"."due", "p_7d39f2a50"."state" AS "obligation_state"
                                        FROM "p_da15c438" AS "p_da15c4380"
                                            INNER JOIN "p_7d39f2a5" AS "p_7d39f2a50" ON "p_7d39f2a50"."entity" = 'return_request_line' AND "p_7d39f2a50"."key" = CAST("p_da15c4380"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a50"."kind" = 'inbound' AND "p_7d39f2a50"."state" IN ('open', 'overdue', 'reopened')) AS "t3"
                                    LEFT JOIN (SELECT "t4"."line_id", COALESCE(SUM(CASE WHEN "p_3fc036840"."condition" = 'ok' THEN "p_3fc036840"."quantity" ELSE 0 END), 0) AS "qty_ok", COALESCE(SUM(CASE WHEN "p_3fc036840"."condition" <> 'ok' THEN "p_3fc036840"."quantity" ELSE 0 END), 0) AS "qty_bad", MAX("p_3fc036840"."received_date") AS "last_received"
                                        FROM (SELECT "p_da15c4381"."line_id", "p_da15c4381"."request_number", "p_da15c4381"."item", "p_da15c4381"."quantity", "p_da15c4381"."way", "p_da15c4381"."customer0" AS "customer", "p_da15c4381"."email" AS "customer_email", "p_7d39f2a51"."id" AS "obligation_id", "p_7d39f2a51"."due", "p_7d39f2a51"."state" AS "obligation_state"
                                                FROM "p_da15c438" AS "p_da15c4381"
                                                    INNER JOIN "p_7d39f2a5" AS "p_7d39f2a51" ON "p_7d39f2a51"."entity" = 'return_request_line' AND "p_7d39f2a51"."key" = CAST("p_da15c4381"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a51"."kind" = 'inbound' AND "p_7d39f2a51"."state" IN ('open', 'overdue', 'reopened')) AS "t4"
                                            LEFT JOIN "p_3fc03684" AS "p_3fc036840" ON "t4"."line_id" = "p_3fc036840"."line_id"
                                        GROUP BY "t4"."line_id") AS "t7" ON "t3"."line_id" = "t7"."line_id") AS "t8"
                            LEFT JOIN (SELECT "t10"."line_id", CASE WHEN "t10"."_ttrp_a_n17_0" IS NULL THEN NULL ELSE COALESCE("t15"."_ttrp_n_n17_0", 0) END AS "days_open"
                                FROM (SELECT "t9"."line_id", "t9"."request_number", "t9"."item", "t9"."quantity", "t9"."way", "t9"."customer", "t9"."customer_email", "t9"."obligation_id", "t9"."due", "t9"."obligation_state", "p_f7cce9af"."recipe", "p_f7cce9af"."run", "p_f7cce9af"."entity", "p_f7cce9af"."key", "p_f7cce9af"."kind", "p_f7cce9af"."due" AS "due0", "p_f7cce9af"."state", "p_f7cce9af"."fulfilled_by", "p_f7cce9af"."fulfilled_at", "p_f7cce9af"."created_at", "p_f7cce9af"."created_at" AS "_ttrp_a_n17_0"
                                        FROM (SELECT "p_da15c4382"."line_id", "p_da15c4382"."request_number", "p_da15c4382"."item", "p_da15c4382"."quantity", "p_da15c4382"."way", "p_da15c4382"."customer0" AS "customer", "p_da15c4382"."email" AS "customer_email", "p_7d39f2a52"."id" AS "obligation_id", "p_7d39f2a52"."due", "p_7d39f2a52"."state" AS "obligation_state"
                                                FROM "p_da15c438" AS "p_da15c4382"
                                                    INNER JOIN "p_7d39f2a5" AS "p_7d39f2a52" ON "p_7d39f2a52"."entity" = 'return_request_line' AND "p_7d39f2a52"."key" = CAST("p_da15c4382"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a52"."kind" = 'inbound' AND "p_7d39f2a52"."state" IN ('open', 'overdue', 'reopened')) AS "t9"
                                            INNER JOIN "p_f7cce9af" ON "t9"."obligation_id" = "p_f7cce9af"."id") AS "t10"
                                    LEFT JOIN (SELECT "t13"."_ttrp_a_n17_0" AS "_ttrp_k_n17_0__ttrp_a_n17_0", COUNT("p_23e6f28a"."_ttrp_d_n17_0") AS "_ttrp_n_n17_0"
                                        FROM (SELECT "p_f7cce9af0"."created_at" AS "_ttrp_a_n17_0"
                                                FROM (SELECT "p_da15c4383"."line_id", "p_da15c4383"."request_number", "p_da15c4383"."item", "p_da15c4383"."quantity", "p_da15c4383"."way", "p_da15c4383"."customer0" AS "customer", "p_da15c4383"."email" AS "customer_email", "p_7d39f2a53"."id" AS "obligation_id", "p_7d39f2a53"."due", "p_7d39f2a53"."state" AS "obligation_state"
                                                        FROM "p_da15c438" AS "p_da15c4383"
                                                            INNER JOIN "p_7d39f2a5" AS "p_7d39f2a53" ON "p_7d39f2a53"."entity" = 'return_request_line' AND "p_7d39f2a53"."key" = CAST("p_da15c4383"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a53"."kind" = 'inbound' AND "p_7d39f2a53"."state" IN ('open', 'overdue', 'reopened')) AS "t11"
                                                    INNER JOIN "p_f7cce9af" AS "p_f7cce9af0" ON "t11"."obligation_id" = "p_f7cce9af0"."id"
                                                GROUP BY "p_f7cce9af0"."created_at") AS "t13"
                                            INNER JOIN "p_23e6f28a" ON "t13"."_ttrp_a_n17_0" < "p_23e6f28a"."_ttrp_d_n17_0" AND "p_23e6f28a"."_ttrp_d_n17_0" <= :as_of
                                        GROUP BY "t13"."_ttrp_a_n17_0") AS "t15" ON "t10"."_ttrp_a_n17_0" = "t15"."_ttrp_k_n17_0__ttrp_a_n17_0") AS "t16" ON "t8"."line_id" = "t16"."line_id") AS "t17"
                    LEFT JOIN (SELECT "t18"."line_id", COUNT("p_4fd248ed"."run") AS "reminders"
                        FROM (SELECT "p_da15c4384"."line_id", "p_da15c4384"."request_number", "p_da15c4384"."item", "p_da15c4384"."quantity", "p_da15c4384"."way", "p_da15c4384"."customer0" AS "customer", "p_da15c4384"."email" AS "customer_email", "p_7d39f2a54"."id" AS "obligation_id", "p_7d39f2a54"."due", "p_7d39f2a54"."state" AS "obligation_state"
                                FROM "p_da15c438" AS "p_da15c4384"
                                    INNER JOIN "p_7d39f2a5" AS "p_7d39f2a54" ON "p_7d39f2a54"."entity" = 'return_request_line' AND "p_7d39f2a54"."key" = CAST("p_da15c4384"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a54"."kind" = 'inbound' AND "p_7d39f2a54"."state" IN ('open', 'overdue', 'reopened')) AS "t18"
                            LEFT JOIN "p_4fd248ed" ON "t18"."line_id" = "p_4fd248ed"."line_id" AND "p_4fd248ed"."route" = 'remind'
                        GROUP BY "t18"."line_id") AS "t19" ON "t17"."line_id" = "t19"."line_id") AS "t20"
        WHERE "t20"."route" = 'complete'
        GROUP BY "line_id") AS "t23" ON "t2"."line_id" = "t23"."line_id"
